import sys, json

def parse(s):
    t = s.split()
    if len(t) != 2:
        return None
    a, b = int(t[0]), int(t[1])
    return {'a': a, 'b': b}

def render(c):
    return f"{c['a']} {c['b']}"

def valid(c):
    return -100 <= c['a'] <= 100 and -100 <= c['b'] <= 100

def solve(s):
    c = parse(s)
    if c is None:
        return 'INVALID'
    return str(c['a'] + c['b'])

def generate(seed, index, mode):
    if mode == 'random':
        import random
        r = random.Random(seed + index)
        a = r.randint(-100, 100)
        b = r.randint(-100, 100)
        return {'a': a, 'b': b}
    elif mode == 'adversarial':
        cases = []
        for val in [-100, 100, 0]:
            cases.append({'a': val, 'b': val})
        cases.append({'a': 100, 'b': -100})
        return cases[index % len(cases)]
    elif mode == 'exhaustive':
        cases = []
        for a in range(-100, 101):
            for b in range(-100, 101):
                cases.append({'a': a, 'b': b})
        return cases[index % len(cases)]
    return None

def shrink(c):
    cases = []
    if c['a'] != 0:
        cases.append({'a': 0, 'b': c['b']})
    if c['b'] != 0:
        cases.append({'a': c['a'], 'b': 0})
    if c['a'] != -100:
        cases.append({'a': c['a'] // 2, 'b': c['b']})
    if c['b'] != -100:
        cases.append({'a': c['a'], 'b': c['b'] // 2})
    return cases[:16]

